/* 取某标签的子类名 */
window.subOfTag = function (tag) {
  var v = window.TAG2SUB[tag];
  if (!v) return null;
  return [window.IMPL_FIELDS[v[0]], window.IMPL_SUBS[v[1]]];
};
/* 取某标签隐含的标签 */
window.implOfTag = function (tag) {
  return window.IMPLICATIONS[tag] || null;
};
